# Phase 75 Stack Startup Script\n# Starts Phase 75 containers WITHOUT rebuilding or recomposing\n\nparam(\n    [switch]$Detached = $true,\n    [switch]$NoBuild = $true,\n    [string]$ComposeFile = \"docker-compose.phase75-standalone.yml\"\n)\n\nWrite-Host \"\"\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"Phase 75 Stack Startup\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"\"\n\n# Check if Docker is running\nWrite-Host \"[1/4] Checking Docker...\" -ForegroundColor Cyan\ntry {\n    $dockerVersion = docker --version 2>$null\n    if ($LASTEXITCODE -eq 0) {\n        Write-Host \"✅ Docker is running\" -ForegroundColor Green\n        Write-Host \"   $dockerVersion\" -ForegroundColor Gray\n    } else {\n        throw \"Docker not available\"\n    }\n} catch {\n    Write-Host \"❌ Docker is not running\" -ForegroundColor Red\n    Write-Host \"   Please start Docker Desktop\" -ForegroundColor Yellow\n    exit 1\n}\n\n# Check if compose file exists\nWrite-Host \"\"\nWrite-Host \"[2/4] Checking Compose File...\" -ForegroundColor Cyan\nif (Test-Path $ComposeFile) {\n    Write-Host \"✅ Compose file found: $ComposeFile\" -ForegroundColor Green\n} else {\n    Write-Host \"❌ Compose file not found: $ComposeFile\" -ForegroundColor Red\n    exit 1\n}\n\n# Create .env if not exists\nWrite-Host \"\"\nWrite-Host \"[3/4] Checking Environment...\" -ForegroundColor Cyan\nif (-not (Test-Path \".env\")) {\n    Write-Host \"Creating .env file...\" -ForegroundColor Yellow\n    @\"\nQDRANT_API_KEY=qdrant-key-phase75\nMINIO_ROOT_USER=minioadmin\nMINIO_ROOT_PASSWORD=minioadmin\n\"@ | Out-File -FilePath \".env\" -Encoding UTF8\n    Write-Host \"✅ .env file created\" -ForegroundColor Green\n} else {\n    Write-Host \"✅ .env file exists\" -ForegroundColor Green\n}\n\n# Start containers (no rebuild)\nWrite-Host \"\"\nWrite-Host \"[4/4] Starting Phase 75 Stack...\" -ForegroundColor Cyan\nWrite-Host \"   (No rebuild, no recompose)\" -ForegroundColor Gray\n\n$composeArgs = @(\"--file\", $ComposeFile)\n\nif ($Detached) {\n    $composeArgs += \"--detach\"\n}\n\nif ($NoBuild) {\n    $composeArgs += \"--no-build\"\n}\n\n$composeArgs += \"up\"\n\nWrite-Host \"\"\nWrite-Host \"Running: docker-compose $($composeArgs -join ' ')\" -ForegroundColor Gray\nWrite-Host \"\"\n\ntry {\n    & docker-compose @composeArgs\n    \n    if ($LASTEXITCODE -eq 0) {\n        Write-Host \"\"\n        Write-Host \"✅ Phase 75 Stack Started Successfully\" -ForegroundColor Green\n    } else {\n        Write-Host \"\"\n        Write-Host \"⚠️ Docker Compose returned exit code: $LASTEXITCODE\" -ForegroundColor Yellow\n    }\n} catch {\n    Write-Host \"\"\n    Write-Host \"❌ Failed to start stack\" -ForegroundColor Red\n    Write-Host \"   Error: $($_.Exception.Message)\" -ForegroundColor Red\n    exit 1\n}\n\n# Wait for services to be ready\nWrite-Host \"\"\nWrite-Host \"Waiting for services to be ready...\" -ForegroundColor Cyan\nStart-Sleep -Seconds 5\n\n# Check service health\nWrite-Host \"\"\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"Service Status\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"\"\n\n$services = @(\n    @{ Name = \"Qdrant\"; Port = 6334; Path = \"/health\" },\n    @{ Name = \"Embedding Service\"; Port = 8011; Path = \"/health\" },\n    @{ Name = \"Summary Service\"; Port = 8012; Path = \"/health\" },\n    @{ Name = \"Pipeline Orchestrator\"; Port = 3011; Path = \"/health\" },\n    @{ Name = \"Redis\"; Port = 6380; Path = \"\" },\n    @{ Name = \"MinIO\"; Port = 9010; Path = \"/minio/health/live\" }\n)\n\nforeach ($service in $services) {\n    $url = \"http://localhost:$($service.Port)$($service.Path)\"\n    try {\n        $response = Invoke-WebRequest -Uri $url -TimeoutSec 2 -ErrorAction Stop\n        Write-Host \"✅ $($service.Name) - Ready (port $($service.Port))\" -ForegroundColor Green\n    } catch {\n        Write-Host \"⏳ $($service.Name) - Starting (port $($service.Port))\" -ForegroundColor Yellow\n    }\n}\n\nWrite-Host \"\"\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"Next Steps\" -ForegroundColor Green\nWrite-Host \"========================================\" -ForegroundColor Green\nWrite-Host \"\"\nWrite-Host \"1. Test Qdrant API:\" -ForegroundColor Cyan\nWrite-Host \"   .\\test-phase75-qdrant.ps1\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"2. View logs:\" -ForegroundColor Cyan\nWrite-Host \"   docker logs qdrant-phase75-r3-cache\" -ForegroundColor Yellow\nWrite-Host \"   docker logs embedding-gemma-phase75\" -ForegroundColor Yellow\nWrite-Host \"   docker logs summary-service-phase75\" -ForegroundColor Yellow\nWrite-Host \"   docker logs pipeline-orchestrator-phase75\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"3. Stop stack:\" -ForegroundColor Cyan\nWrite-Host \"   docker-compose -f docker-compose.phase75-standalone.yml down\" -ForegroundColor Yellow\nWrite-Host \"\"\nWrite-Host \"4. Connect UI to WebSocket:\" -ForegroundColor Cyan\nWrite-Host \"   ws://localhost:3011/api/pipeline/ws\" -ForegroundColor Yellow\nWrite-Host \"\"\n"